<section class="page-heading"><div><p class="eyebrow">PRÉPAREZ VOS AFFAIRES ET VOS TENUES</p><h1>Valise virtuelle</h1><p class="subheading">Une pièce physique n’apparaît qu’une seule fois, même si plusieurs tenues du voyage l’utilisent.</p></div><a class="button primary" href="<?= e(url('trip-show',['id'=>0])) ?>">＋ Préparer un voyage</a></section>
<?php if(!$trips): ?><div class="empty-state"><div class="empty-illustration">⌑</div><h3>Aucun voyage préparé</h3><p>Créez un voyage, sélectionnez des tenues et suivez votre valise.</p><a class="button primary" href="<?= e(url('trip-show',['id'=>0])) ?>">Créer mon voyage</a></div><?php else: ?><div class="trip-grid"><?php foreach($trips as $trip): ?><a class="trip-card" href="<?= e(url('trip-show',['id'=>$trip['id']])) ?>"><span class="eyebrow"><?= e($trip['destination']?:'VOYAGE') ?></span><h2><?= e($trip['name']) ?></h2><p><?= e(date('d.m.Y',strtotime($trip['start_date']))) ?> — <?= e(date('d.m.Y',strtotime($trip['end_date']))) ?></p><div class="budget-progress"><i style="width:<?= $trip['item_count']?round((int)$trip['packed_count']/(int)$trip['item_count']*100):0 ?>%"></i></div><small><?= e($trip['packed_count']) ?> / <?= e($trip['item_count']) ?> affaires préparées</small></a><?php endforeach; ?></div><?php endif; ?>
